X.today(() => { const c = X.cur(); if (!c) return null; const r = rec(c.id, X.day()); return { title: '🕯️ 睡前三件好事', rows: [{ t: r.me ? '已交换' : '今晚', x: r.me ? X.esc(r.me[0]) : '还没写', go: `gyxGoodOpen('${c.id}')` }] }; }, 'gyxGood');
